        out.putNull("physical_core");out.putNull("assault_projection");if(value.physical()!=null&&value.inputs()!=null&&value.family()!=null&&!value.missing().contains("same_capture_subject_Province_context")){out.set("physical_core",encodePhysical(value.physical()));out.put("physical_input_basis",value.physical().inputBasis()).put("context_basis",value.physical().contextBasis());}if(value.assault()!=null)out.set("assault_projection",value.assault().toJson());
